import {Button, Link, Text} from '@smart/react-components';
import React from 'react';
import {MySubscriptionsI18nKeys} from '../../../../../generated/i18n/MySubscriptions';
import {type Service, SubscriptionStatus} from '../../../../bff/subscriptions';
import {useAppModelLoggedInContext} from '../../../hooks/use-app-model';
import {useProductDetailsNavigationTarget} from '../../../hooks/use-product-details-navigation';
import {useTranslations} from '../../../hooks/use-translations';
import {getModelDisplayName} from '../../../utils/get-model-display-name';
import styles from './subscriptions-card.module.scss';

const baseClass = `subscriptions-card`;

export interface SubscriptionsCardProps {
  service: Service;
  modelCode: string;
  renewable: boolean | undefined;
  onDetailsClick: (serviceID: string) => void;
}

export const SubscriptionsCard: React.FC<SubscriptionsCardProps> = ({
  service,
  modelCode,
  renewable,
  onDetailsClick,
}) => {
  const translate = useTranslations();

  const {
    content: {myOrders},
  } = useAppModelLoggedInContext();

  const productDetails = useProductDetailsNavigationTarget(
    myOrders.productDetailsPageReference,
    service.productCode,
    `accessoryCode`,
  );

  const handleDetailsClick = () => {
    onDetailsClick(service.serviceID);
  };

  const isRenewable = service.status === SubscriptionStatus.ACTIVE && renewable;
  const isActive = service.status === SubscriptionStatus.ACTIVE;
  const model = getModelDisplayName(modelCode);

  return (
    <div className={styles[baseClass]}>
      <div className={styles[`${baseClass}__top-section`]}>
        <Text
          variant="p-200"
          color="c-mid-contrast"
          as="p"
          className={styles[`${baseClass}__product-name`]}
        >
          {model}
        </Text>
        <Text
          variant="hl-200"
          color="c-high-contrast"
          className={styles[`${baseClass}__product-type`]}
        >
          {service.productName}
        </Text>
      </div>

      <div className={styles[`${baseClass}__bottom-section`]}>
        <Text variant="p-200" color="c-high-contrast">
          {translate(MySubscriptionsI18nKeys[`mySubscriptions.orderStatus`])}
        </Text>
        <div className={styles[`${baseClass}__status-indicator`]}>
          <div
            className={styles[`${baseClass}__status-dot`]}
            data-status={service.status.toLowerCase()}
          />

          <Text
            variant="p-100"
            color="c-high-contrast"
            className={styles[`${baseClass}__status-text`]}
          >
            {service.status}
          </Text>

          {service.endDate && isActive && (
            <Text
              variant="p-100"
              color="c-high-contrast"
              className={
                isRenewable ? styles[`${baseClass}__expire-date`] : undefined
              }
            >
              {translate(MySubscriptionsI18nKeys[`mySubscriptions.expireOn`])}
              {` `}
              {service.endDate}
            </Text>
          )}
        </div>

        {(isRenewable || service.status === SubscriptionStatus.INACTIVE) && (
          <Button
            asChild
            className={styles[`${baseClass}__renew-button`]}
            mode={300}
          >
            <Link href={productDetails?.href} onClick={productDetails?.onClick}>
              {translate(
                MySubscriptionsI18nKeys[`mySubscriptions.renewPackage`],
              )}
            </Link>
          </Button>
        )}

        <Button
          className={styles[`${baseClass}__details-button`]}
          variant="secondary"
          onClick={handleDetailsClick}
          mode={300}
        >
          {translate(MySubscriptionsI18nKeys[`mySubscriptions.details`])}
        </Button>
      </div>
    </div>
  );
};

export default SubscriptionsCard;

