import {Button, Flex, Link, Spacer, Text} from '@smart/react-components';
import {Notification} from '@smart/web-components';
import React from 'react';
import {SubscriptionDetailsI18nKeys} from '../../../../../generated/i18n/SubscriptionDetails';
import type {ServiceDetailResponse} from '../../../../bff/service-details';
import {SubscriptionStatus} from '../../../../bff/subscriptions';
import {useTranslations} from '../../../hooks/use-translations';
import styles from './SubscriptionGeneralInfo.module.scss';

const baseClass = `subscription-general-info`;
const cn = (suffix: string) => styles[`${baseClass}__${suffix}`];

interface SubscriptionGeneralInfoProps {
  subscriptionDetails: ServiceDetailResponse;
  productDetails:
    | {
        href: string;
        onClick: (event: React.MouseEvent<HTMLElement, MouseEvent>) => void;
      }
    | undefined;
}

const getNotificationContent = (
  status: string,
  isExp: boolean,
  translate: ReturnType<typeof useTranslations>,
) => {
  const effectiveStatus = isExp && status === SubscriptionStatus.ACTIVE ? `About to expire` : status;

  switch (effectiveStatus) {
    case `About to expire`:
      return {
        message: translate(
          SubscriptionDetailsI18nKeys[
            `subscriptionDetails.notification.aboutToExpire.message`
          ],
        ),
        showCta: true,
        ctaLabel: translate(
          SubscriptionDetailsI18nKeys[`subscriptionDetails.notification.cta`],
        ),
      };
    case SubscriptionStatus.INACTIVE:
      return {
        message: translate(
          SubscriptionDetailsI18nKeys[
            `subscriptionDetails.notification.expired.message`
          ],
        ),
        showCta: true,
        ctaLabel: translate(
          SubscriptionDetailsI18nKeys[`subscriptionDetails.notification.cta`],
        ),
      };
    case SubscriptionStatus.PROCESSING:
      return {
        message: translate(
          SubscriptionDetailsI18nKeys[
            `subscriptionDetails.notification.processing.message`
          ],
        ),
        showCta: false,
      };
    default:
      return null;
  }
};

export const SubscriptionGeneralInfo: React.FC<
  SubscriptionGeneralInfoProps
> = ({subscriptionDetails, productDetails}) => {
  const translate = useTranslations();

  const notification = getNotificationContent(
    subscriptionDetails.status,
    subscriptionDetails.isExp,
    translate,
  );

  const isAboutToExpireOrExpired =
    subscriptionDetails.isExp ||
    subscriptionDetails.status === SubscriptionStatus.INACTIVE;

  const isProcessing =
    subscriptionDetails.status === SubscriptionStatus.PROCESSING;

  return (
    <div className={styles[baseClass]}>
      <div className={cn(`wrapper`)}>
        <Flex direction="column" gap={300}>
          <div className={cn(`vin-item`)}>
            <Text
              variant="p-200"
              color="c-high-contrast"
              as="p"
              margin-bottom="100"
            >
              {translate(
                SubscriptionDetailsI18nKeys[
                  `subscriptionDetails.generalInfo.vin`
                ],
              )}
            </Text>
            <Text variant="lbl-200" color="c-high-contrast" as="p">
              {subscriptionDetails.vinNumber}
            </Text>
          </div>

          {/* Start Date (only for Processing status) */}
          {isProcessing && subscriptionDetails.startDate && (
            <div className={cn(`start-date`)}>
              <Text
                variant="p-100"
                color="c-high-contrast"
                as="p"
                margin-bottom="100"
              >
                {translate(
                  SubscriptionDetailsI18nKeys[
                    `subscriptionDetails.generalInfo.activeOn`
                  ],
                )}
              </Text>
              <Text variant="lbl-200" as="p" color="sig-error">
                {subscriptionDetails.startDate}
              </Text>
            </div>
          )}

          <div className={cn(`end-date`)}>
            <Text variant="p-100" as="p" margin-bottom="100">
              {translate(
                SubscriptionDetailsI18nKeys[
                  `subscriptionDetails.generalInfo.expiryDate`
                ],
              )}
            </Text>
            <Text
              variant="lbl-200"
              as="p"
              className={
                isAboutToExpireOrExpired ? cn(`error-text`) : undefined
              }
            >
              {subscriptionDetails.endDate}
            </Text>
          </div>
        </Flex>

        <div>
          <Text variant="p-200" color="c-high-contrast">
            {translate(
              SubscriptionDetailsI18nKeys[
                `subscriptionDetails.generalInfo.status.label`
              ],
            )}
          </Text>

          <Flex alignContent={`center`} gap={100}>
            <div
              className={styles[`${baseClass}__status-dot`]}
              data-status={subscriptionDetails.status.toLowerCase()}
            />

            <Text
              variant="p-100"
              color="c-high-contrast"
              className={styles[`${baseClass}__status-text`]}
            >
              {subscriptionDetails.status}
            </Text>
          </Flex>

          <Spacer height={400} />

          {notification && (
            <Notification
              text={
                <>
                  <Text variant="p-300" color="--dc-accent" as="p">
                    {notification.message}
                  </Text>
                  {notification.showCta ? (
                    <Button
                      className={styles[`${baseClass}__notification-button`]}
                      asChild
                      variant="primary"
                    >
                      <Link
                        href={productDetails?.href}
                        onClick={productDetails?.onClick}
                      >
                        {notification.ctaLabel}
                      </Link>
                    </Button>
                  ) : null}
                </>
              }
              variant="informational"
              className={cn(`notification`)}
            />
          )}
        </div>
      </div>
    </div>
  );
};

