import {usePriceType} from '@smart/feature-app';
import {Divider, Text} from '@smart/react-components';
import type {MarketId} from '@smart/types';
import {DynamicMediaPicture} from '@smart/web-components';
import React from 'react';
import {MyOrdersI18nKeys} from '../../../../../generated/i18n/MyOrders';
import {SubscriptionDetailsI18nKeys} from '../../../../../generated/i18n/SubscriptionDetails';
import {type PaymentType} from '../../../../bff/el-web-client';
import {useAppModelLoggedInContext} from '../../../hooks/use-app-model';
import {useLocale} from '../../../hooks/use-locale';
import {useTranslations} from '../../../hooks/use-translations';
import {getVatLabel} from '../../../utils/get-vat-label';
import styles from './SubscriptionProductDisplay.module.scss';

const baseClass = `subscription-product-display`;
const cn = (suffix: string) => styles[`${baseClass}__${suffix}`];

interface SubscriptionProductDisplayProps {
  productCode: string;
  productName: string;
  paymentTypeCode: PaymentType;
  totalPriceFormatted: string;
  vatLabel?: string;
}

export const SubscriptionProductDisplay: React.FC<
  SubscriptionProductDisplayProps
> = ({
  productCode,
  productName,
  paymentTypeCode,
  totalPriceFormatted,
  vatLabel: vatLabelProp,
}) => {
  const {imageUrlTemplate} = useAppModelLoggedInContext();
  const imageUrl = imageUrlTemplate.replace(
    `IMAGE_NAME_PLACEHOLDER`,
    `${productCode ?? ``}`,
  );
  const translate = useTranslations();
  const {marketId} = useLocale();
  const [priceType] = usePriceType();

  const vatLabel =
    vatLabelProp ??
    getVatLabel({
      marketId: marketId.toLowerCase() as MarketId,
      labels: {
        includesVatLabel: translate(
          SubscriptionDetailsI18nKeys[
            `subscriptionDetails.product.includesTaxLabel`
          ],
        ),
        excludeVatLabel: translate(
          SubscriptionDetailsI18nKeys[
            `subscriptionDetails.product.excludesTaxLabel`
          ],
        ),
      },
      paymentType: paymentTypeCode,
      priceType,
      config: useAppModelLoggedInContext().commonConfig,
    });

  return (
    <div className={styles[baseClass]}>
      <div className={cn(`wrapper`)}>
        {/* Sold by */}
        <div className={cn(`sold-by`)}>
          <Text
            variant="p-200"
            as="p"
            color="c-mid-contrast"
            className={cn(`sold-by-label`)}
          >
            {translate(
              SubscriptionDetailsI18nKeys[`subscriptionDetails.product.soldBy`],
            )}
          </Text>
          <Text
            variant="lbl-200"
            as="p"
            color="c-mid-contrast"
            className={cn(`sold-by-value`)}
          >
            {translate(
              MyOrdersI18nKeys[
                `myOrders.contractPartner.cashbuy.vehicle.default`
              ],
            )}
          </Text>
        </div>

        {/* Product Image and Details */}
        <div className={cn(`product-section`)}>
          <DynamicMediaPicture
            className={cn(`product-image`)}
            imageAltText={productName}
            imageConfigs={[
              {
                aspectRatio: `4-3`,
                sizes: `90vw`,
                media: `(min-width: 375px) and (max-width: 1024px)`,
              },
              {
                aspectRatio: `4-3`,
                sizes: `40vw`,
                media: `(min-width: 1025px)`,
              },
            ]}
            imageUrl={imageUrl}
            initialIsInView={false}
          />

          <div className={cn(`product-info`)}>
            <Text
              variant="hl-200"
              color="c-high-contrast"
              className={cn(`product-name`)}
            >
              {productName}
            </Text>
          </div>
        </div>

        {/* Payment Information */}
        <div className={cn(`payment-section`)}>
          <div className={cn(`payment-row`)}>
            <Text variant="lbl-100" color="c-mid-contrast" as="p">
              {translate(
                SubscriptionDetailsI18nKeys[
                  `subscriptionDetails.product.paymentType`
                ],
              )}
            </Text>
            <Text variant="lbl-100" color="c-high-contrast" as="p">
              {translate(
                SubscriptionDetailsI18nKeys[
                  `subscriptionDetails.product.cashbuy`
                ],
              )}
            </Text>
          </div>

          <Divider
            orientation="horizontal"
            margin={{
              y: 200,
            }}
          />

          <div className={cn(`payment-row`)}>
            <Text variant="lbl-100" color="c-mid-contrast" as="p">
              {translate(
                SubscriptionDetailsI18nKeys[
                  `subscriptionDetails.product.price`
                ],
              )}
            </Text>
            <div className={cn(`price-wrapper`)}>
              <Text variant="lbl-100" color="c-high-contrast" as="p">
                {totalPriceFormatted}
              </Text>
              <Text variant="cap-300" color="c-mid-contrast" as="div">
                {vatLabel}
              </Text>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
